using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly string baseUrl;

    private string? method;
    private string? path;
    private string? contentType;
    private string? body;

    public HttpPaymentGatewayTests()
    {
        // Retry on port collisions between parallel runs.
        for (var attempt = 0; ; attempt++)
        {
            var port = Random.Shared.Next(20000, 60000);
            var prefix = $"http://127.0.0.1:{port}/";
            try
            {
                listener.Prefixes.Add(prefix);
                listener.Start();
                baseUrl = prefix;
                break;
            }
            catch (HttpListenerException) when (attempt < 10)
            {
                listener.Prefixes.Clear();
            }
        }

        client = new HttpClient { BaseAddress = new Uri(baseUrl) };
    }

    [Fact]
    public async Task Sends_a_json_post_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        var server = Serve(200, """{"status":"approved"}""");

        await new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);
        await server;

        Assert.Equal("POST", method);
        Assert.Equal("/v1/authorizations", path);
        Assert.StartsWith("application/json", contentType);
        using var json = JsonDocument.Parse(body!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_approved()
    {
        var server = Serve(200, """{"status":"approved"}""");
        var outcome = await Authorize();
        await server;
        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_answer_is_declined()
    {
        var server = Serve(200, """{"status":"declined"}""");
        var outcome = await Authorize();
        await server;
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_payment_required_refusal_is_declined()
    {
        var server = Serve(402, """{"error":"card_declined"}""");
        var outcome = await Authorize();
        await server;
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_payment_required_refusal_with_an_empty_body_is_declined()
    {
        var server = Serve(402, "");
        var outcome = await Authorize();
        await server;
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unrecognised_status_is_never_treated_as_approved()
    {
        var server = Serve(200, """{"status":"pending"}""");
        var outcome = await Authorize();
        await server;
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_response_without_a_status_is_never_treated_as_approved()
    {
        var server = Serve(200, """{"result":"approved"}""");
        var outcome = await Authorize();
        await server;
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Errors_other_than_a_refusal_surface_as_failures_not_decisions(int status)
    {
        var server = Serve(status, """{"error":"nope"}""");
        await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        await server;
    }

    [Fact]
    public async Task A_non_json_success_body_surfaces_as_a_failure()
    {
        var server = Serve(200, "<html>oops</html>");
        await Assert.ThrowsAsync<JsonException>(Authorize);
        await server;
    }

    private Task<AuthorizationOutcome> Authorize() =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-1", new Money(10m, "USD"), CancellationToken.None);

    private async Task Serve(int status, string responseBody)
    {
        var context = await listener.GetContextAsync();
        method = context.Request.HttpMethod;
        path = context.Request.Url!.AbsolutePath;
        contentType = context.Request.ContentType;
        using (var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8))
            body = await reader.ReadToEndAsync();

        var bytes = Encoding.UTF8.GetBytes(responseBody);
        context.Response.StatusCode = status;
        context.Response.ContentType = "application/json";
        context.Response.ContentLength64 = bytes.Length;
        await context.Response.OutputStream.WriteAsync(bytes);
        context.Response.Close();
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }
}
